    shl.b64 %rd6, %rd4, 2;
    add.u64 %rd7, %rd6, 4;
    setp.le.u64 %p1, %rd7, %rd3;
    @!%p1 bra SCALAR;
    shl.b64 %rd8, %rd6, 2;
    add.u64 %rd9, %rd1, %rd8;
    add.u64 %rd10, %rd2, %rd8;
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd9];
    tanh.approx.f32 %f1, %f1;
    tanh.approx.f32 %f2, %f2;
    tanh.approx.f32 %f3, %f3;
    tanh.approx.f32 %f4, %f4;
    st.global.v4.f32 [%rd10], {%f1, %f2, %f3, %f4};
    add.u64 %rd4, %rd4, %rd5;
    bra VEC_LOOP;
SCALAR:
    setp.lt.u64 %p2, %rd6, %rd3;
    @!%p2 bra DONE;
SCALAR_LOOP:
    shl.b64 %rd13, %rd6, 2;
    add.u64 %rd14, %rd1, %rd13;
    add.u64 %rd15, %rd2, %rd13;
    ld.global.f32 %f1, [%rd14];
    tanh.approx.f32 %f2, %f1;
    st.global.f32 [%rd15], %f2;
    add.u64 %rd6, %rd6, 1;
    setp.lt.u64 %p2, %rd6, %rd3;
    @%p2 bra SCALAR_LOOP;
DONE:
    ret;
